async (page) => {
  const results=[];
  const check=(condition,label)=>{if(!condition)throw new Error(label);results.push(label)};
  await page.getByRole('button',{name:'My workspace',exact:true}).click();
  await page.getByRole('button',{name:'Add a component',exact:true}).click();
  await page.getByRole('button',{name:'Document',exact:true}).click();
  const card=page.locator('.module').last();
  const id=await card.getAttribute('data-item');
  const initial=await card.boundingBox(),stage=await page.locator('#surface').boundingBox();
  const header=await card.locator('.module-header').boundingBox();
  await page.mouse.move(header.x+header.width/2,header.y+18);
  await page.mouse.down();await page.mouse.move(stage.x+3,stage.y+3,{steps:12});await page.mouse.up();
  const position=await card.evaluate(el=>({x:parseFloat(el.style.left),y:parseFloat(el.style.top)}));
  check(position.x<0&&position.y<0,'Dragging reaches negative world coordinates without a top/left wall');
  check(position.x%16===0&&position.y%16===0,'Drop snaps to the world grid');
  await page.getByRole('button',{name:'Fit all content',exact:true}).click();
  const before=await card.boundingBox();
  await page.getByRole('button',{name:'Zoom out',exact:true}).click();
  const after=await card.boundingBox();
  check(after.width<before.width,'Zoom changes scale');
  const retained=await card.evaluate(el=>({x:parseFloat(el.style.left),y:parseFloat(el.style.top)}));
  check(retained.x===position.x&&retained.y===position.y,'Zoom preserves world positions');
  await page.mouse.move(stage.x+stage.width-8,stage.y+80);await page.mouse.wheel(4500,3000);
  await page.getByRole('button',{name:'Add a component',exact:true}).click();
  await page.getByRole('button',{name:'Document',exact:true}).click();
  await page.getByRole('button',{name:'Fit all content',exact:true}).click();
  const cards=await page.locator('.module').evaluateAll(els=>els.map(el=>{const r=el.getBoundingClientRect();return{x:r.x,y:r.y,right:r.right,bottom:r.bottom}}));
  check(cards.length===2,'Offscreen components remain present');
  check(cards.every(r=>r.x>=stage.x-1&&r.y>=stage.y-1&&r.right<=stage.x+stage.width+1&&r.bottom<=stage.y+stage.height-100),'Fit all recovers widely separated components using their actual bounds');
  await page.locator(`[data-focus="${id}"]`).click();
  const recovered=await page.locator(`[data-item="${id}"]`).boundingBox();
  check(recovered.x+recovered.width>stage.x&&recovered.x<stage.x+stage.width,'Rail navigation recovers a particular component');
  await page.locator('#zoom-level').click();
  const focused=page.locator(`[data-item="${id}"]`);
  await page.locator(`[data-focus="${id}"]`).click();
  const resize=await focused.locator('.resize-handle').boundingBox();
  const cameraBefore=await page.locator('#world').getAttribute('style');
  const widthBefore=await focused.evaluate(el=>parseFloat(el.style.width));
  await page.mouse.move(resize.x+8,resize.y+8);await page.mouse.down();await page.mouse.move(resize.x+68,resize.y+48,{steps:8});await page.mouse.up();
  check(await focused.evaluate(el=>parseFloat(el.style.width))>widthBefore,'Resize changes the component dimensions');
  check(await page.locator('#world').getAttribute('style')===cameraBefore,'Resizing does not pan the canvas');
  await page.reload();
  check(await page.locator(`[data-item="${id}"]`).count()===1,'Placement survives reload');
  await page.getByRole('button',{name:'Studio',exact:true}).click();
  await page.getByRole('button',{name:'Context graph',exact:true}).click();
  await page.locator('[data-node="resources:studio"]').press('Enter');
  await page.getByRole('button',{name:'Inspect Working brief',exact:true}).press('Enter');
  check(await page.locator('body').getAttribute('class')==='graph-mode','Inspecting a resource stays in the graph');
  check(await page.locator('.graph-inspection').count()===1,'Resource expands within its graph node');
  const inspection=await page.locator('.graph-inspection').boundingBox();
  check(inspection.width>300,'Graph inspection is readable after a zoomed-out graph');
  await page.getByRole('button',{name:'History',exact:true}).click();
  check(await page.locator('.module').count()===1,'History does not spawn another window');
  await page.getByRole('button',{name:'Content',exact:true}).click();
  await page.getByRole('textbox',{name:'Document content',exact:true}).fill('Graph-local edit verification.');
  await page.getByRole('button',{name:'History',exact:true}).click();
  check((await page.locator('.graph-inspection').innerText()).includes('Edited'),'Graph editing records a revision');
  await page.getByRole('button',{name:'Close graph inspection',exact:true}).click();
  await page.getByRole('button',{name:'Expand Weekend workshop',exact:true}).press('Enter');
  await page.locator('[data-node="conversations:weekend"]').press('Enter');
  await page.locator('[data-node="channel:weekend-general"]').press('Enter');
  check((await page.locator('.project-section.selected').innerText()).includes('Weekend workshop'),'Cross-project channel inspection updates the selected project');
  check(await page.locator('body').getAttribute('class')==='graph-mode','Cross-project conversation review stays in graph');
  check(await page.getByRole('button',{name:/Physics/}).count()===0,'Physics has no disable control');
  return results;
}
